mapper.select:
SELECT p.id, p.shop_id, p.name, p.category, d1.enum_name AS category_name, p.price, p.stock, p.image_url, p.remark, p.status, d2.enum_name AS status_name, p.create_time, p.update_time FROM otps_product p LEFT JOIN otps_dict d1 ON d1.dict_id = 'product:category' AND d1.enum_code = p.category LEFT JOIN otps_dict d2 ON d2.dict_id = 'product:status' AND d2.enum_code = p.status
AND p.id = #{query.id}
AND p.name LIKE '%' || #{query.name} || '%'
AND p.category = #{query.category}
AND p.status = #{query.status}
AND p.shop_id = #{shopId}
ORDER BY p.create_time DESC
